package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

func main() {
	all_transaction := []Transaction{}
	idCounter := 1

	for {
		fmt.Println("1. Добавить операцию\n2. Список операций\n3. Баланс\n4. Удаление операции\n5. Статистика\n6. Выход")
		var user_choise int
		fmt.Scanln(&user_choise)
		switch user_choise {
		case 1:
			var err error
			all_transaction, err = UserCreateTransaction(all_transaction, &idCounter)
			if err != nil {
				fmt.Println(err)
			} else {
				fmt.Printf("Операция успешно создана\n\n")
			}
		case 2:
			for _, transaction := range all_transaction {
				fmt.Printf("Операция №%d\nСумма:%.2f\nТип операции:%s\nОписание:%s\nКатегория:%s\nДата:%s\n\n",
					transaction.id, transaction.amount, transaction.transaction_type, transaction.description, transaction.category, transaction.date)
			}
		case 3:
			fmt.Printf("Ваш баланс составляет:%.2f\n\n", calculateBalance(all_transaction))
		case 4:
			fmt.Println("Выберите операцию для удаления")
		case 5:
			fmt.Println("4. Статистика")
		case 6:
			fmt.Println("5. Выход")
			return
		default:
			fmt.Println("Введено некорректное значение")
		}
	}
}

type Transaction struct {
	id               int
	transaction_type string
	amount           float64
	category         string
	description      string
	date             string
}

func NewTransaction(transaction_type, category, description, date string, id int, amount float64) Transaction {
	return Transaction{
		id:               id,
		transaction_type: transaction_type,
		amount:           amount,
		category:         category,
		description:      description,
		date:             date,
	}
}

func calculateBalance(all_transaction []Transaction) float64 {
	var balance float64
	for _, transaction := range all_transaction {
		if transaction.transaction_type == "Доход" {
			balance += transaction.amount
		} else {
			balance -= transaction.amount
		}
	}
	return balance
}
func UserCreateTransaction(all_transaction []Transaction, idCounter *int) ([]Transaction, error) {
	id := *idCounter
	fmt.Println("Введите тип операции")
	var transaction_type string
	fmt.Scanln(&transaction_type)
	if transaction_type == "Доход" || transaction_type == "Расход" {
		fmt.Println("Введите категорию")
		var category string
		fmt.Scanln(&category)
		fmt.Println("Введите описание операции")
		var description string
		fmt.Scanln(&description)
		fmt.Println("Введите сумму операции")
		var amount float64
		fmt.Scan(&amount)
		transaction := NewTransaction(transaction_type, category, description, time.Now().Format("02.01.2006 15:04:05"), id, amount)
		all_transaction = append(all_transaction, transaction)
		*idCounter++
		return all_transaction, nil
	}
	return all_transaction, errors.New("Введен некорректный тип операции, попробуйте снова\n")
}

package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

func main() {
	all_transaction := []Transaction{}
	idCounter := 1

	for {
		fmt.Println("1. Добавить операцию\n2. Список операций\n3. Баланс\n4. Удаление операции\n5. Статистика\n6. Выход")
		var user_choise int
		fmt.Scanln(&user_choise)
		switch user_choise {
		case 1:
			var err error
			all_transaction, err = UserCreateTransaction(all_transaction, &idCounter)
			if err != nil {
				fmt.Println(err)
			} else {
				fmt.Printf("Операция успешно создана\n\n")
			}
		case 2:
			for _, transaction := range all_transaction {
				fmt.Printf("Операция №%d\nСумма:%.2f\nТип операции:%s\nОписание:%s\nКатегория:%s\nДата:%s\n\n",
					transaction.id, transaction.amount, transaction.transaction_type, transaction.description, transaction.category, transaction.date)
			}
		case 3:
			fmt.Printf("Ваш баланс составляет:%.2f\n\n", calculateBalance(all_transaction))
		case 4:
			fmt.Println("Выберите операцию для удаления")
		case 5:
			fmt.Println("4. Статистика")
		case 6:
			fmt.Println("5. Выход")
			return
		default:
			fmt.Println("Введено некорректное значение")
		}
	}
}

type Transaction struct {
	id               int
	transaction_type string
	amount           float64
	category         string
	description      string
	date             string
}

func NewTransaction(transaction_type, category, description, date string, id int, amount float64) Transaction {
	return Transaction{
		id:               id,
		transaction_type: transaction_type,
		amount:           amount,
		category:         category,
		description:      description,
		date:             date,
	}
}

func calculateBalance(all_transaction []Transaction) float64 {
	var balance float64
	for _, transaction := range all_transaction {
		if transaction.transaction_type == "Доход" {
			balance += transaction.amount
		} else {
			balance -= transaction.amount
		}
	}
	return balance
}
func UserCreateTransaction(all_transaction []Transaction, idCounter *int) ([]Transaction, error) {
	id := *idCounter
	fmt.Println("Введите тип операции")
	var transaction_type string
	fmt.Scanln(&transaction_type)
	transaction_type = strings.TrimSpace(transaction_type)
	if transaction_type == "Доход" || transaction_type == "Расход" {
		fmt.Println("Введите категорию")
		var category string
		fmt.Scanln(&category)
		category = strings.TrimSpace(category)
		fmt.Println("Введите описание операции")
		var description string
		fmt.Scanln(&description)
		description = strings.TrimSpace(description)
		fmt.Println("Введите сумму операции")
		var amount_str string
		fmt.Scanln(&amount_str)
		amount_str = strings.TrimSpace(amount_str)
		amount, err := strconv.ParseFloat(amount_str, 64)
		if err != nil {
			return all_transaction, errors.New("Некорректная сумма\n")
		}
		transaction := NewTransaction(transaction_type, category, description, time.Now().Format("02.01.2006 15:04:05"), id, amount)
		all_transaction = append(all_transaction, transaction)
		*idCounter++
		return all_transaction, nil
	}
	return all_transaction, errors.New("Введен некорректный тип операции, попробуйте снова\n")
}
